import{_ as a,o as s,c as t,ag as r}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md"}'),o={name:"features/dashboard.md"};function n(i,e,d,l,m,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>Overview is the default home page for work across this backend. Team, scope and harness filters are independent of the saved native harness and local project.</p><h2 id="read-the-observations" tabindex="-1">Read the observations <a class="header-anchor" href="#read-the-observations" aria-label="Permalink to &quot;Read the observations&quot;">​</a></h2><p>Counts describe the complete filtered dataset: queued, active, review, attention, finished and unknown tracking. Follow <a href="/docs/features/work.html">Work</a> to inspect records. Finished is not independently reviewed delivery, reliability or time saved. Read failures remain visible rather than becoming zero counts.</p><p>Automation separates configured scopes/enablement from effective intake. Runtime normal/recovery-only/unknown mode, scheduler state and runtime time are independent observations. Recovery-only blocks normal intake; missing evidence stays unknown. Stale/never-polled counts cover eligible polling, not paused or blocked scopes. See <a href="/docs/features/repositories.html">Repositories</a>.</p><h2 id="refresh-and-next-steps" tabindex="-1">Refresh and next steps <a class="header-anchor" href="#refresh-and-next-steps" aria-label="Permalink to &quot;Refresh and next steps&quot;">​</a></h2><p>Visible observations refresh periodically. Response/runtime timestamps differ from the last repository poll; loading a page does not trigger GitHub polling or enable automation. Empty configuration retains manual Teams, Live sessions and Harnesses entry points.</p><h2 id="native-summaries-moved-to-harnesses" tabindex="-1">Native summaries moved to Harnesses <a class="header-anchor" href="#native-summaries-moved-to-harnesses" aria-label="Permalink to &quot;Native summaries moved to Harnesses&quot;">​</a></h2><p>The former provider/project dashboard is available as Configuration summary under <a href="/docs/features/harnesses.html">Harnesses</a> for implemented providers. Claude Code retains its native configuration/context summary; Codex uses supported configuration, inventory, live sessions and Plans. Codex usage/context/transcript parity is unavailable. Native summaries and project settings do not filter factory work.</p>',9)])])}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
